# Derived from Studio backend/studio/command_filter.py at 5b39c3abf34523c69fb761f7dd174c710d3a7eb1.
# Minimal export; comments/docstrings removed; machine-specific fallback paths cleared.
from __future__ import annotations
import re
from typing import Optional
_DENY: list[tuple[re.Pattern, str]] = [(re.compile('\\brm\\b[^\\n;|&]*\\s-[a-z]*r', re.I), "recursive 'rm -r' delete is blocked"), (re.compile('\\brm\\b[^\\n;|&]*--recursive', re.I), "recursive 'rm --recursive' delete is blocked"), (re.compile('\\brm\\b[^\\n;|&]*\\s-[a-z]*f', re.I), "forced 'rm -f' delete is blocked"), (re.compile('\\brm\\b\\s+--force', re.I), "forced 'rm --force' delete is blocked"), (re.compile('\\b(rmdir|rd)\\b[^\\n;|&]*\\s/s', re.I), 'recursive Windows dir delete is blocked'), (re.compile('\\bdel\\b[^\\n;|&]*\\s/s', re.I), "recursive Windows 'del /s' is blocked"), (re.compile('Remove-Item[^\\n;|&]*-Recurse', re.I), "recursive 'Remove-Item -Recurse' is blocked"), (re.compile('\\bri\\b[^\\n;|&]*-Recurse', re.I), "recursive 'ri -Recurse' is blocked"), (re.compile('\\bfind\\b[^\\n]*-delete', re.I), "'find ... -delete' bulk delete is blocked"), (re.compile('\\bmkfs\\b', re.I), 'filesystem format (mkfs) is blocked'), (re.compile('\\bdd\\b[^\\n]*\\bof=', re.I), 'raw disk write (dd of=) is blocked'), (re.compile('\\bdiskpart\\b', re.I), 'diskpart is blocked'), (re.compile('\\bfdisk\\b', re.I), 'fdisk is blocked'), (re.compile('\\bparted\\b', re.I), 'parted is blocked'), (re.compile('\\bwipefs\\b', re.I), 'wipefs is blocked'), (re.compile('\\bshred\\b', re.I), 'shred is blocked'), (re.compile('\\bmkswap\\b', re.I), 'mkswap is blocked'), (re.compile('>\\s*/dev/[sh]d', re.I), 'writing to a raw block device is blocked'), (re.compile('\\bof=/dev/', re.I), 'writing to a raw block device is blocked'), (re.compile(':\\s*>\\s*/dev/sd', re.I), 'writing to a raw block device is blocked'), (re.compile('\\b(format)\\b\\s+[a-z]:', re.I), 'drive format is blocked'), (re.compile('\\bcipher\\b\\s+/w', re.I), 'secure-wipe (cipher /w) is blocked'), (re.compile(':\\s*\\(\\s*\\)\\s*\\{', re.I), 'fork bomb is blocked'), (re.compile('\\(\\)\\s*\\{\\s*:\\s*\\|\\s*:', re.I), 'fork bomb is blocked'), (re.compile('\\bshutdown\\b', re.I), 'shutdown is blocked'), (re.compile('\\breboot\\b', re.I), 'reboot is blocked'), (re.compile('\\bpoweroff\\b', re.I), 'poweroff is blocked'), (re.compile('\\bhalt\\b', re.I), 'halt is blocked'), (re.compile('\\binit\\b\\s+[06]\\b', re.I), 'init 0/6 is blocked'), (re.compile('\\b(Stop|Restart)-Computer\\b', re.I), 'Stop/Restart-Computer is blocked'), (re.compile('\\bsudo\\b', re.I), 'sudo / privilege escalation is blocked'), (re.compile('\\bsu\\b\\s+-', re.I), 'su privilege escalation is blocked'), (re.compile('\\brunas\\b', re.I), 'runas privilege escalation is blocked'), (re.compile('\\bchmod\\b[^\\n;|&]*\\s-[a-z]*R', re.I), 'recursive chmod is blocked'), (re.compile('\\bchown\\b[^\\n;|&]*\\s-[a-z]*R', re.I), 'recursive chown is blocked'), (re.compile('\\bchmod\\b\\s+0?777\\s+/', re.I), 'chmod 777 on a root path is blocked'), (re.compile('\\btakeown\\b', re.I), 'takeown is blocked'), (re.compile('\\bicacls\\b', re.I), 'icacls is blocked'), (re.compile('\\b(curl|wget|fetch)\\b[^\\n]*\\|\\s*(sudo\\s+)?(ba|z|fi|c)?sh\\b', re.I), 'pipe-to-shell from a network fetch is blocked'), (re.compile('\\b(curl|wget)\\b[^\\n]*\\|\\s*(sudo\\s+)?python', re.I), 'pipe-to-interpreter from a network fetch is blocked'), (re.compile('Invoke-WebRequest[^\\n]*\\|\\s*(iex|Invoke-Expression)', re.I), 'IWR | Invoke-Expression is blocked'), (re.compile('\\biex\\b\\s*\\(', re.I), 'Invoke-Expression (iex) is blocked'), (re.compile('\\bkill\\b\\s+-9?\\s*-1\\b', re.I), 'kill -1 (all processes) is blocked'), (re.compile('\\bkillall\\b', re.I), 'killall is blocked'), (re.compile('\\bpkill\\b', re.I), 'pkill is blocked'), (re.compile('\\breg\\b\\s+delete', re.I), 'registry delete is blocked'), (re.compile('Remove-Item[^\\n]*HK(LM|CU|CR|U|CC):', re.I), 'registry hive delete is blocked'), (re.compile('\\bgit\\b[^\\n]*\\bpush\\b[^\\n]*(--force|-f\\b)', re.I), 'git force-push is blocked'), (re.compile('\\bgit\\b[^\\n]*\\bclean\\b[^\\n]*-[a-z]*f[a-z]*d', re.I), 'git clean -fd is blocked')]
MAX_COMMAND_LEN = 8000

def check_command(command: str) -> Optional[str]:
    if not isinstance(command, str) or not command.strip():
        return 'empty command'
    if len(command) > MAX_COMMAND_LEN:
        return f'command too long (> {MAX_COMMAND_LEN} chars)'
    for pat, reason in _DENY:
        if pat.search(command):
            return reason
    return None

def assert_safe(command: str) -> None:
    reason = check_command(command)
    if reason:
        raise ValueError(f'command blocked for safety: {reason}')
